import 'package:cached_network_image/cached_network_image.dart';
import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../models/product.dart';
import '../state/app_state.dart';

class ProductScreen extends StatelessWidget { const ProductScreen({super.key}); @override Widget build(BuildContext context) { final product = ModalRoute.of(context)!.settings.arguments as Product; return Scaffold(appBar: AppBar(title: const Text('Ürün'), actions: [IconButton(onPressed: () async { try { await context.read<AppState>().toggleFavorite(product.id); if (context.mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Favoriler güncellendi'))); } catch (e) { if (context.mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.toString()))); } }, icon: const Icon(Icons.favorite_border))]), body: ListView(padding: const EdgeInsets.all(20), children: [AspectRatio(aspectRatio: 1, child: product.image.isEmpty ? const Icon(Icons.image_outlined, size: 80) : CachedNetworkImage(imageUrl: product.image, fit: BoxFit.cover)), const SizedBox(height: 20), Text(product.name, style: const TextStyle(fontSize: 24, fontWeight: FontWeight.w800)), const SizedBox(height: 10), Text('${product.price.toStringAsFixed(2)} ₺', style: const TextStyle(fontSize: 20, fontWeight: FontWeight.w700)), if (product.variations.isNotEmpty) ...[const SizedBox(height: 20), const Text('Beden / renk seçimi', style: TextStyle(fontWeight: FontWeight.w700)), ...product.variations.map((item) => ListTile(title: Text('${item['label'] ?? item['name'] ?? item}'), leading: const Icon(Icons.check_box_outline_blank)))], if (product.description.isNotEmpty) Padding(padding: const EdgeInsets.symmetric(vertical: 20), child: Text(product.description)), const SizedBox(height: 20), FilledButton(onPressed: () async { await context.read<AppState>().addToCart(product); if (context.mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Ürün sepete eklendi'))); }, child: const Text('Sepete ekle'))])); } }
